import os, sys, ssl, socket, threading
ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
ctx.load_cert_chain(sys.argv[1])
ctx.minimum_version = ssl.TLSVersion.TLSv1_2
ctx.maximum_version = ssl.TLSVersion.TLSv1_2
ctx.set_ciphers('AES128-SHA256:@SECLEVEL=1')
a, b = socket.socketpair()
def to_sock():
    try:
        while True:
            d = os.read(0, 4096)
            if not d: break
            a.sendall(d)
    except OSError:
        pass
    try: a.shutdown(socket.SHUT_WR)
    except OSError: pass
def to_stdout():
    try:
        while True:
            d = a.recv(4096)
            if not d: break
            os.write(1, d)
    except OSError:
        pass
threading.Thread(target=to_sock, daemon=True).start()
threading.Thread(target=to_stdout).start()  # non-daemon: flush response before exit
try:
    tls = ctx.wrap_socket(b, server_side=True)
    tls.settimeout(4)
    data = b''
    while b'\n' not in data:
        c = tls.recv(4096)
        if not c: break
        data += c
    tls.sendall(b'SRV:' + data)
    tls.close()
    b.close()  # lets the non-daemon relay thread observe EOF and exit
except Exception as e:
    os.write(2, ('helper: %r\n' % e).encode())
